namespace HakutaiKagami.Core.Contracts;
public static partial class BattlefieldRules
{
 static BattleWeather AtUnit(ContractWorld w,EngagementUnit u)=>Weather(w,RegionalCampaign.Site(ContinuousWorld.Nearest(u.Position)),w.ElapsedSeconds);
 static bool RangedReady(ContractWorld w,EngagementUnit u){var gear=Loadout(w,u.Unit.Id,w.ElapsedSeconds,w.CommitSequence+1);int count=Math.Min(gear.Equipped,(int)u.Unit.Soldiers);if(count==0)return false;var weather=AtUnit(w,u);return gear.Kind switch{TroopKind.Gun=>w.ElapsedSeconds%(weather==BattleWeather.Rain?30:10)==0&&Carried(w,u.Unit.Id,"powder",w.ElapsedSeconds,w.CommitSequence)>=count&&Carried(w,u.Unit.Id,"bullet",w.ElapsedSeconds,w.CommitSequence)>=count,TroopKind.Bow=>w.ElapsedSeconds%5==0&&Carried(w,u.Unit.Id,"arrow",w.ElapsedSeconds,w.CommitSequence)>=count,_=>false};}
 static bool Reach(ContractWorld w,EngagementUnit a,EngagementUnit b){var gear=Loadout(w,a.Unit.Id,w.ElapsedSeconds,w.CommitSequence+1);long range=ContactCombat.RadiusMm;if(RangedReady(w,a)){range=gear.Kind==TroopKind.Gun?80000:60000;if(WorldGround.KindAt(w,a.Position)=="forest"||WorldGround.KindAt(w,b.Position)=="forest")range/=2;}range=Math.Min(range,SightRange(w,a.Position,w.ElapsedSeconds));return RegionalGround.Distance(a.Position,b.Position)<=range&&Math.Abs(a.Height-b.Height)<=(range>ContactCombat.RadiusMm?12000:ContactCombat.HeightToleranceMm);}
 static int Damage(ContractWorld w,EngagementUnit a,EngagementUnit b){var gear=Loadout(w,a.Unit.Id,w.ElapsedSeconds,w.CommitSequence+1);int armed=Math.Min(gear.Equipped,(int)a.Unit.Soldiers);int coefficient=gear.Kind switch{TroopKind.Spear=>100,TroopKind.Bow=>RangedReady(w,a)?120:50,TroopKind.Gun=>RangedReady(w,a)?180:40,TroopKind.Cavalry=>WorldGround.KindAt(w,a.Position)=="forest"?50:140,_=>20};if(gear.Kind==TroopKind.Cavalry&&Carried(w,a.Unit.Id,"fodder",w.ElapsedSeconds,w.CommitSequence)<armed)coefficient=50;long power=armed*coefficient+(a.Unit.Soldiers-armed)*30;int valor=a.Unit.Id==TempleMilitary.Unit?55:CharacterDevelopment.EffectiveAt(w,a.Unit.Commander,DevelopmentAbility.Valor,w.ElapsedSeconds);power=power*(50+valor)/100;if(a.Height>b.Height)power=power*120/100;else if(a.Height<b.Height)power=power*80/100;return Math.Max(1,(int)Math.Min(b.Unit.Soldiers,power/1000));}
 public static EngagementResult Resolve(ContractWorld w,WorldEngagementSnapshot s){if(!Enabled(w))return FieldEngagement.Resolve(s.At,s.Units,s.Mandates,s.Hostilities);var result=FieldEngagement.Resolve(s.At,s.Units,s.Mandates,s.Hostilities,(a,b)=>Reach(w,a,b),(a,b)=>Damage(w,a,b),(a,b)=>TempleMilitary.Defends(w,a,b));var uses=new List<BattlefieldExpense>();foreach(var id in result.Strikes.Select(x=>x.Attacker).Distinct()){var unit=s.Units.Single(u=>u.Unit.Id==id);var gear=Loadout(w,id,s.At,w.CommitSequence+1);int count=Math.Min(gear.Equipped,(int)unit.Unit.Soldiers);if(RangedReady(w,unit)){foreach(var good in gear.Kind==TroopKind.Gun?new[]{"powder","bullet"}:new[]{"arrow"})uses.Add(new(id,good,count));}if(gear.Kind==TroopKind.Cavalry&&count>0&&s.At%60==0&&Carried(w,id,"fodder",s.At,w.CommitSequence)>=count)uses.Add(new(id,"fodder",count));}return result with{Expenses=uses.ToArray(),Casualties=result.Losses.Select(l=>Partition(w,s.Units.Single(u=>u.Unit.Id==l.Unit),l)).ToArray()};}
}
